parameters.jsonBody:
={{ JSON.stringify({
  systemInstruction: { parts: [{ text: "You classify emails for a college student. Return ONLY JSON with keys: priority, topic, confidence, summary. priority must be one of: important, normal, spam. topic must be one of: placements, ads, academics, other. Important means placement drives, interview or test schedules, exam notices, deadlines, and messages from professors or the college. Ads means promotions, newsletters and marketing. Spam means unsolicited or suspicious mail. confidence is a number from 0 to 1. summary is one short sentence. If unsure, use topic other and a lower confidence." }] },
  contents: [{ role: "user", parts: [{ text: "From: " + $json.From + "\nSubject: " + $json.Subject + "\nBody: " + $json.snippet }] }],
  generationConfig: { temperature: 0, responseMimeType: "application/json" }
}) }}

parameters.jsCode:
const replies = $input.all();
const mails = $('Gmail Trigger').all();

return replies.map((item, i) => {
  const mail = mails[i].json;
  let result;

  try {
    const raw = item.json.candidates[0].content.parts[0].text;
    result = JSON.parse(raw);
  } catch (e) {
    // Safety net: if the reply is broken, mark it for manual review
    result = { priority: "normal", topic: "other", confidence: 0, summary: "Classification failed" };
  }

  return {
    json: {
      gmail_id: mail.id,
      sender: mail.From,
      subject: mail.Subject,
      priority: result.priority,
      topic: result.topic,
      confidence: result.confidence,
      summary: result.summary,
      processed_at: new Date().toISOString()
    }
  };
});
